import { describe, it, expect } from 'vitest';
import { parseYarnLockfile } from './yarn.js';

describe('yarn lockfile parser', () => {
  it('should parse yarn v1 lockfile format', () => {
    const lockfile = `
# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.
# yarn lockfile v1

lodash@^4.17.21:
  version "4.17.21"
  resolved "https://registry.yarnpkg.com/lodash/-/lodash-4.17.21.tgz"
  integrity sha512-...

react@^18.0.0, react@^18.2.0:
  version "18.2.0"
  resolved "https://registry.yarnpkg.com/react/-/react-18.2.0.tgz"
  integrity sha512-...
`;

    const result = parseYarnLockfile(lockfile);

    expect(result.get('lodash')).toBe('4.17.21');
    expect(result.get('react')).toBe('18.2.0');
  });

  it('should parse scoped packages', () => {
    const lockfile = `
"@types/node@^20.0.0":
  version "20.11.0"
  resolved "https://registry.yarnpkg.com/@types/node/-/node-20.11.0.tgz"

"@babel/core@^7.20.0":
  version "7.23.0"
  resolved "https://registry.yarnpkg.com/@babel/core/-/core-7.23.0.tgz"
`;

    const result = parseYarnLockfile(lockfile);

    expect(result.get('@types/node')).toBe('20.11.0');
    expect(result.get('@babel/core')).toBe('7.23.0');
  });

  it('should handle packages without quotes', () => {
    const lockfile = `
typescript@^5.0.0:
  version "5.3.3"
  resolved "https://registry.yarnpkg.com/typescript/-/typescript-5.3.3.tgz"
`;

    const result = parseYarnLockfile(lockfile);

    expect(result.get('typescript')).toBe('5.3.3');
  });

  it('should handle multiple version ranges for same package', () => {
    const lockfile = `
"semver@^7.0.0", "semver@^7.3.5", "semver@^7.5.0":
  version "7.5.4"
  resolved "https://registry.yarnpkg.com/semver/-/semver-7.5.4.tgz"
`;

    const result = parseYarnLockfile(lockfile);

    // Should only capture the first occurrence
    expect(result.get('semver')).toBe('7.5.4');
  });

  it('should handle empty lockfile', () => {
    const lockfile = `# yarn lockfile v1`;

    const result = parseYarnLockfile(lockfile);

    expect(result.size).toBe(0);
  });

  it('should handle version without quotes', () => {
    const lockfile = `
lodash@^4.17.21:
  version 4.17.21
  resolved "https://registry.yarnpkg.com/lodash/-/lodash-4.17.21.tgz"
`;

    const result = parseYarnLockfile(lockfile);

    expect(result.get('lodash')).toBe('4.17.21');
  });
});
